  "version": 2,
  "imports": [
    "Mathlib.LinearAlgebra.UnitaryGroup",
    "Mathlib.Data.ZMod.Basic",
    "Mathlib.Analysis.Complex.Basic",
    "Mathlib.Tactic.Group",
    "Mathlib.Tactic.NoncommRing"
  ],
  "source": "namespace Contribution\n\nopen Matrix\n\n/-! ## Periodic hypercubic lattice, link variables and gauge transformations -/\n\n/-- Sites of the periodic hypercubic lattice `(ℤ/Lℤ)^d`. -/\nabbrev Site (d L : ℕ) : Type := Fin d → ZMod L\n\n/-- The lattice unit vector in direction `μ`. -/\ndef e {d L : ℕ} (μ : Fin d) : Site d L := Pi.single μ 1\n\n/-- A lattice gauge field: one group element on each oriented link `(x, x + e μ)`. -/\nabbrev LinkConfig (G : Type) (d L : ℕ) : Type := Site d L → Fin d → G\n\n/-- A lattice gauge transformation: one group element per site. -/\nabbrev GaugeTransform (G : Type) (d L : ℕ) : Type := Site d L → G\n\nsection General\n\nvariable {G : Type} [Group G] {d L : ℕ}\n\n/-- The plaquette holonomy `U_{x,μ} U_{x+μ,ν} U_{x+ν,μ}⁻¹ U_{x,ν}⁻¹`. -/\ndef plaquette (U : LinkConfig G d L) (x : Site d L) (μ ν : Fin d) : G :=\n  U x μ * U (x + e μ) ν * (U (x + e ν) μ)⁻¹ * (U x ν)⁻¹\n\n/-- Gauge action `U_{x,μ} ↦ g_x U_{x,μ} g_{x+μ}⁻¹`. -/\ndef gaugeAct (g : GaugeTransform G d L) (U : LinkConfig G d L) : LinkConfig G d L :=\n  fun x μ => g x * U x μ * (g (x + e μ))⁻¹\n\n/-- Plaquettes transform covariantly: by conjugation at their base point. -/\ntheorem plaquette_gaugeAct (g : GaugeTransform G d L) (U : LinkConfig G d L)\n    (x : Site d L) (μ ν : Fin d) :\n    plaquette (gaugeAct g U) x μ ν = g x * plaquette U x μ ν * (g x)⁻¹ := by\n  simp only [plaquette, gaugeAct]\n  rw [add_right_comm x (e ν) (e μ)]\n  group\n\n/-- Reversing the orientation of a plaquette inverts its holonomy. -/\ntheorem plaquette_swap (U : LinkConfig G d L) (x : Site d L) (μ ν : Fin d) :\n    plaquette U x ν μ = (plaquette U x μ ν)⁻¹ := by\n  simp only [plaquette]\n  group\n\ntheorem plaquette_self (U : LinkConfig G d L) (x : Site d L) (μ : Fin d) :\n    plaquette U x μ μ = 1 := by\n  simp only [plaquette]\n  group\n\n/-- A function on the gauge group invariant under conjugation. -/\ndef IsClassFunction (f : G → ℝ) : Prop := ∀ a b : G, f (a * b * a⁻¹) = f b\n\n/-- The lattice action `∑_x ∑_{μ<ν} f(U_p)` with plaquette weight `f`. -/\ndef latticeAction [NeZero L] (f : G → ℝ) (U : LinkConfig G d L) : ℝ :=\n  ∑ x : Site d L, ∑ μ : Fin d, ∑ ν : Fin d, if μ < ν then f (plaquette U x μ ν) else 0\n\n/-- Any lattice action built from a class function is gauge invariant. -/\ntheorem latticeAction_gaugeAct [NeZero L] (f : G → ℝ) (hf : IsClassFunction f)\n    (g : GaugeTransform G d L) (U : LinkConfig G d L) :\n    latticeAction f (gaugeAct g U) = latticeAction f U := by\n  have hf' : ∀ a b : G, f (a * b * a⁻¹) = f b := hf\n  simp only [latticeAction, plaquette_gaugeAct, hf']\n\nend General\n\n/-! ## The Wilson plaquette weight on `U(n)` -/\n\nsection Wilson\n\nvariable {n : ℕ}\n\n/-- The Wilson plaquette weight `n - Re tr M`. -/\nnoncomputable def wilsonWeight (n : ℕ) (M : Matrix (Fin n) (Fin n) ℂ) : ℝ :=\n  (n : ℝ) - (trace M).re\n\n/-- Squared Frobenius distance `‖M - 1‖²` of a matrix to the identity. -/\nnoncomputable def frobDistSq (n : ℕ) (M : Matrix (Fin n) (Fin n) ℂ) : ℝ :=\n  ∑ i : Fin n, ∑ j : Fin n, Complex.normSq ((M - 1) j i)\n\n/-- For unitary `M`, the Wilson weight equals half the squared Frobenius distance to `1`. -/\ntheorem two_mul_wilsonWeight {M : Matrix (Fin n) (Fin n) ℂ}\n    (hM : M ∈ unitaryGroup (Fin n) ℂ) : 2 * wilsonWeight n M = frobDistSq n M := by\n  have hU : star M * M = 1 := (mem_unitaryGroup_iff').mp hM\n  have key : star (M - 1) * (M - 1) = (1 + 1) - star M - M := by\n    rw [star_sub, star_one]\n    have : (star M - 1) * (M - 1) = star M * M - star M - M + 1 := by noncomm_ring\n    rw [this, hU]\n    abel\n  have hentry : ∀ A : Matrix (Fin n) (Fin n) ℂ,\n      trace (star A * A) = ∑ i : Fin n, ∑ j : Fin n, (Complex.normSq (A j i) : ℂ) := by\n    intro A\n    simp only [trace, diag, Matrix.mul_apply, Matrix.star_apply, Complex.star_def,\n      Complex.normSq_eq_conj_mul_self]\n  have h := congrArg Complex.re ((hentry (M - 1)).symm.trans (congrArg trace key))\n  simp only [Complex.re_sum, Complex.ofReal_re, trace_sub, trace_add, trace_one,\n    Fintype.card_fin, Complex.sub_re, Complex.add_re, Complex.natCast_re] at h\n  rw [star_eq_conjTranspose, trace_conjTranspose, Complex.star_def, Complex.conj_re] at h\n  rw [frobDistSq, h, wilsonWeight]\n  ring\n\ntheorem frobDistSq_nonneg (M : Matrix (Fin n) (Fin n) ℂ) : 0 ≤ frobDistSq n M :=\n  Finset.sum_nonneg fun _ _ => Finset.sum_nonneg fun _ _ => Complex.normSq_nonneg _\n\ntheorem wilsonWeight_nonneg {M : Matrix (Fin n) (Fin n) ℂ}\n    (hM : M ∈ unitaryGroup (Fin n) ℂ) : 0 ≤ wilsonWeight n M := by\n  have h := two_mul_wilsonWeight hM\n  have := frobDistSq_nonneg (n := n) M\n  linarith\n\ntheorem wilsonWeight_eq_zero_iff {M : Matrix (Fin n) (Fin n) ℂ}\n    (hM : M ∈ unitaryGroup (Fin n) ℂ) : wilsonWeight n M = 0 ↔ M = 1 := by\n  constructor\n  · intro h0\n    have h := two_mul_wilsonWeight hM\n    rw [h0, mul_zero, eq_comm, frobDistSq,\n      Finset.sum_eq_zero_iff_of_nonneg fun i _ =>\n        Finset.sum_nonneg fun j _ => Complex.normSq_nonneg _] at h\n    ext j i\n    have hi := h i (Finset.mem_univ _)\n    rw [Finset.sum_eq_zero_iff_of_nonneg fun j _ => Complex.normSq_nonneg _] at hi\n    have hji := Complex.normSq_eq_zero.mp (hi j (Finset.mem_univ _))\n    rw [Matrix.sub_apply, sub_eq_zero] at hji\n    exact hji\n  · rintro rfl\n    simp [wilsonWeight, trace_one]\n\n/-- Conjugation by a unitary matrix preserves the Wilson weight. -/\ntheorem wilsonWeight_conj {A : Matrix (Fin n) (Fin n) ℂ} (hA : A ∈ unitaryGroup (Fin n) ℂ)\n    (M : Matrix (Fin n) (Fin n) ℂ) : wilsonWeight n (A * M * star A) = wilsonWeight n M := by\n  have ha : star A * A = 1 := (mem_unitaryGroup_iff').mp hA\n  simp only [wilsonWeight]\n  rw [trace_mul_comm, ← Matrix.mul_assoc, ha, Matrix.one_mul]\n\n/-! ### Wilson action for any gauge group with a unitary representation -/\n\nvariable {G : Type} [Group G]\n\n/-- `ρ : G → M_n(ℂ)` is a unitary representation: unitary-valued and multiplicative. -/\ndef IsUnitaryRep (ρ : G → Matrix (Fin n) (Fin n) ℂ) : Prop :=\n  (∀ g : G, ρ g ∈ unitaryGroup (Fin n) ℂ) ∧ ∀ a b : G, ρ (a * b) = ρ a * ρ b\n\n/-- The Wilson action `S_ρ(U) = ∑_x ∑_{μ<ν} (n - Re tr ρ(U_p))`. -/\nnoncomputable def wilsonAction {d L : ℕ} [NeZero L] (ρ : G → Matrix (Fin n) (Fin n) ℂ)\n    (U : LinkConfig G d L) : ℝ :=\n  latticeAction (fun g => wilsonWeight n (ρ g)) U\n\n/-- Every plaquette holonomy is the identity. -/\ndef IsFlat {d L : ℕ} (U : LinkConfig G d L) : Prop := ∀ x μ ν, plaquette U x μ ν = 1\n\n/-- Every plaquette holonomy lies in the kernel of `ρ`. -/\ndef PlaquettesInKer {d L : ℕ} (ρ : G → Matrix (Fin n) (Fin n) ℂ) (U : LinkConfig G d L) :\n    Prop :=\n  ∀ x μ ν, ρ (plaquette U x μ ν) = 1\n\n/-- The representation packaged as a homomorphism into `U(n)`. -/\ndef IsUnitaryRep.hom {ρ : G → Matrix (Fin n) (Fin n) ℂ} (hρ : IsUnitaryRep ρ) :\n    G →* unitaryGroup (Fin n) ℂ :=\n  MonoidHom.mk' (fun g => ⟨ρ g, hρ.1 g⟩) fun a b => Subtype.ext (hρ.2 a b)\n\ntheorem IsUnitaryRep.hom_val {ρ : G → Matrix (Fin n) (Fin n) ℂ} (hρ : IsUnitaryRep ρ)\n    (g : G) : (hρ.hom g).1 = ρ g := rfl\n\ntheorem IsUnitaryRep.map_one {ρ : G → Matrix (Fin n) (Fin n) ℂ} (hρ : IsUnitaryRep ρ) :\n    ρ 1 = 1 := by\n  rw [← hρ.hom_val, _root_.map_one]; rfl\n\ntheorem IsUnitaryRep.map_inv {ρ : G → Matrix (Fin n) (Fin n) ℂ} (hρ : IsUnitaryRep ρ)\n    (g : G) : ρ g⁻¹ = star (ρ g) := by\n  rw [← hρ.hom_val, _root_.map_inv]; rfl\n\ntheorem wilsonAction_gaugeAct {d L : ℕ} [NeZero L] (ρ : G → Matrix (Fin n) (Fin n) ℂ)\n    (hρ : IsUnitaryRep ρ) (g : GaugeTransform G d L) (U : LinkConfig G d L) :\n    wilsonAction ρ (gaugeAct g U) = wilsonAction ρ U := by\n  apply latticeAction_gaugeAct\n  intro a b\n  simp only [hρ.2, hρ.map_inv]\n  exact wilsonWeight_conj (hρ.1 a) (ρ b)\n\ntheorem wilsonAction_nonneg {d L : ℕ} [NeZero L] (ρ : G → Matrix (Fin n) (Fin n) ℂ)\n    (hρ : IsUnitaryRep ρ) (U : LinkConfig G d L) : 0 ≤ wilsonAction ρ U := by\n  unfold wilsonAction latticeAction\n  refine Finset.sum_nonneg fun x _ => Finset.sum_nonneg fun μ _ =>\n    Finset.sum_nonneg fun ν _ => ?_\n  split_ifs\n  · exact wilsonWeight_nonneg (hρ.1 _)\n  · exact le_rfl\n\n/-- The Wilson action vanishes exactly when every plaquette lies in `ker ρ`. -/\ntheorem wilsonAction_eq_zero_iff {d L : ℕ} [NeZero L] (ρ : G → Matrix (Fin n) (Fin n) ℂ)\n    (hρ : IsUnitaryRep ρ) (U : LinkConfig G d L) :\n    wilsonAction ρ U = 0 ↔ PlaquettesInKer ρ U := by\n  have hnn : ∀ x μ ν,\n      0 ≤ (if μ < ν then wilsonWeight n (ρ (plaquette U x μ ν)) else 0) := by\n    intro x μ ν\n    split_ifs\n    · exact wilsonWeight_nonneg (hρ.1 _)\n    · exact le_rfl\n  unfold wilsonAction latticeAction PlaquettesInKer\n  rw [Finset.sum_eq_zero_iff_of_nonneg fun x _ =>\n    Finset.sum_nonneg fun μ _ => Finset.sum_nonneg fun ν _ => hnn x μ ν]\n  constructor\n  · intro h x μ ν\n    have hx := h x (Finset.mem_univ _)\n    rw [Finset.sum_eq_zero_iff_of_nonneg fun μ _ =>\n      Finset.sum_nonneg fun ν _ => hnn x μ ν] at hx\n    have hlt : ∀ μ ν : Fin d, μ < ν → ρ (plaquette U x μ ν) = 1 := by\n      intro μ ν hμν\n      have hμ := hx μ (Finset.mem_univ _)\n      rw [Finset.sum_eq_zero_iff_of_nonneg fun ν _ => hnn x μ ν] at hμ\n      have hν := hμ ν (Finset.mem_univ _)\n      simp only [hμν, ↓reduceIte] at hν\n      exact (wilsonWeight_eq_zero_iff (hρ.1 _)).mp hν\n    rcases lt_trichotomy μ ν with hμν | rfl | hνμ\n    · exact hlt μ ν hμν\n    · rw [plaquette_self, hρ.map_one]\n    · rw [plaquette_swap, hρ.map_inv, hlt ν μ hνμ, star_one]\n  · intro h x _\n    refine Finset.sum_eq_zero fun μ _ => Finset.sum_eq_zero fun ν _ => ?_\n    split_ifs\n    · exact (wilsonWeight_eq_zero_iff (hρ.1 _)).mpr (h x μ ν)\n    · rfl\n\n/-- For a faithful representation the classical vacua are exactly the flat configurations. -/\ntheorem wilsonAction_eq_zero_iff_flat {d L : ℕ} [NeZero L]\n    (ρ : G → Matrix (Fin n) (Fin n) ℂ) (hρ : IsUnitaryRep ρ) (hinj : Function.Injective ρ)\n    (U : LinkConfig G d L) :\n    wilsonAction ρ U = 0 ↔ IsFlat U := by\n  rw [wilsonAction_eq_zero_iff ρ hρ, PlaquettesInKer, IsFlat]\n  have key : ∀ p : G, ρ p = 1 ↔ p = 1 := fun p =>\n    ⟨fun h => hinj (h.trans hρ.map_one.symm), fun h => h ▸ hρ.map_one⟩\n  simp only [key]\n\nend Wilson\n\n/-- Foundations of lattice Yang–Mills on the periodic lattice `(ℤ/Lℤ)^d`:\n(1) every class-function plaquette action is gauge invariant, for any gauge group;\n(2) for a gauge group `G` with a unitary representation `ρ : G → U(n)`, the Wilson action\n`∑_x ∑_{μ<ν} (n - Re tr ρ(U_p))` is gauge invariant and nonnegative, and it vanishes exactly\nwhen every plaquette lies in `ker ρ`; for faithful `ρ`, exactly on flat configurations;\n(3) on `U(n)` the Wilson weight equals half the squared Frobenius distance `‖M - 1‖²`. -/\ntheorem result :\n    (∀ (G : Type) [Group G] (d L : ℕ) [NeZero L] (f : G → ℝ), IsClassFunction f →\n      ∀ (g : GaugeTransform G d L) (U : LinkConfig G d L),\n        latticeAction f (gaugeAct g U) = latticeAction f U) ∧\n    (∀ (G : Type) [Group G] (n d L : ℕ) [NeZero L] (ρ : G → Matrix (Fin n) (Fin n) ℂ),\n      IsUnitaryRep ρ → ∀ U : LinkConfig G d L,\n        (∀ g : GaugeTransform G d L, wilsonAction ρ (gaugeAct g U) = wilsonAction ρ U) ∧\n        0 ≤ wilsonAction ρ U ∧\n        (wilsonAction ρ U = 0 ↔ PlaquettesInKer ρ U) ∧\n        (Function.Injective ρ → (wilsonAction ρ U = 0 ↔ IsFlat U))) ∧\n    (∀ (n : ℕ) (M : Matrix (Fin n) (Fin n) ℂ), M ∈ unitaryGroup (Fin n) ℂ →\n      2 * wilsonWeight n M = frobDistSq n M) := by\n  refine ⟨?_, ?_, ?_⟩\n  · intro G _ d L _ f hf g U\n    exact latticeAction_gaugeAct f hf g U\n  · intro G _ n d L _ ρ hρ U\n    exact ⟨fun g => wilsonAction_gaugeAct ρ hρ g U, wilsonAction_nonneg ρ hρ U,\n      wilsonAction_eq_zero_iff ρ hρ U, fun hinj => wilsonAction_eq_zero_iff_flat ρ hρ hinj U⟩\n  · intro n M hM\n    exact two_mul_wilsonWeight hM\n\nend Contribution\n",
  "theorem": "Contribution.result",
  "dependencies": []
}
","context":"{"title":"Lattice Yang–Mills foundations: gauge invariance and classical vacua of the Wilson action for unitary representations","novelty":"This is the first contribution on this track, so no accepted track results overlap. The mathematics is classical: gauge invariance of the Wilson action is due to Wilson (1974) and is textbook material. Outside this track, Michael R. Douglas's Lean library lgt (github.com/mrdouglasny/lgt, Lean 4.30) already formalizes U(n) Wilson lattice gauge theory, gauge invariance of its Wilson action, the bound Re tr U ≤ n, and a strong-coupling mass-gap theorem. Searching lgt at commit b8793ccf for vacuum or flatness statements, Frobenius identities and faithful-representation hypotheses found none of the following, which are this bundle's increments: the exact identity n − Re tr V = ½‖V − 1‖²_F; the characterization of the zero set of the Wilson action (plaquettes in ker ρ; flat configurations for faithful ρ, including both plaquette orientations via U_p(ν,μ) = U_p(μ,ν)⁻¹); and the statement for an abstract gauge group through a unitary representation rather than U(n) alone. The formal code is original and independent of lgt; no lgt source was copied.","prior_art":[{"reference":"K. G. Wilson, Confinement of quarks, Phys. Rev. D 10, 2445 (1974), https://doi.org/10.1103/PhysRevD.10.2445","relationship":"Introduces the lattice gauge action ∑(1 − Re tr U_p / n) and its gauge invariance. This contribution formalizes that invariance for any class function and any group, and adds the vacuum characterization."},{"reference":"M. R. Douglas, lgt — Lattice Gauge Theory in Lean 4, https://github.com/mrdouglasny/lgt (commit b8793ccf6a51e00e9e2b1685ba191b8626e37137)","relationship":"Prior Lean formalization of U(n) Wilson lattice gauge theory: Wilson action, gauge invariance, Re tr U ≤ n, Gibbs measure and a strong-coupling (β < 1/(32n(d−1))) mass-gap theorem. Overlaps parts (1) and the nonnegativity in (2); it does not contain the Frobenius identity, the zero-set/flatness characterization or the representation-level statement. It uses a different Lean version and is not importable here."},{"reference":"S. Chatterjee, Yang–Mills for probabilists, arXiv:1803.01950, https://arxiv.org/abs/1803.01950","relationship":"Surveys the lattice route (Wilson action, gauge invariance, strong-coupling mass gap, open continuum-limit problems) that these lemmas serve; standard background, nothing formal is imported."},{"reference":"K. Osterwalder and E. Seiler, Gauge field theories on a lattice, Ann. Phys. 110 (1978) 440, https://doi.org/10.1016/0003-4916(78)90039-8","relationship":"Classical rigorous strong-coupling mass gap for lattice gauge theories, whose setup (Wilson action, gauge invariance, positivity) is the context for this infrastructure; not formalized here."},{"reference":"A. Jaffe and E. Witten, Quantum Yang–Mills theory (Clay problem statement), https://www.claymath.org/millennium/yang-mills-the-maths-gap/","relationship":"Defines the target problem. This contribution is lattice-regularized classical infrastructure only and does not address existence of the continuum theory or the mass gap."}],"dependencies":[],"attribution":"The Lean definitions, statements and proofs were written by an AI coding agent (Claude, Anthropic) operating on behalf of the wallet holder, including the prior-art search and comparison against lgt. The wallet holder directed the submission. No third-party Lean code is included.","limitations":"This is classical, finite-lattice infrastructure. It proves nothing about the quantum theory: no Haar/Gibbs measure, no reflection positivity, transfer matrix, correlation decay or mass gap, and no continuum limit, so it does not address the existence or mass-gap parts of the Clay problem. The zero-set result identifies flat configurations, not gauge orbits: on the torus a flat configuration need not be gauge-equivalent to the trivial one (nontrivial holonomy around noncontractible cycles)